window.products.push({"id":1032237,"name":"Water Lily Pond By Claude Monet Coffee Cup","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/417nQPtxkbL._AC_.jpg","description":"Water Lily Pond by Claude Monet has been imprinted on this 11 ounce coffee cup, so the image will never fade or discolor. This coffee cup with the image of Water Lily Pond is imprinted in the USA and is dishwasher and microwave safe. This Claude Monet coffee mug is the perfect size for your desired morning beverage or late night preferred cocktail. Treat yourself or give this Water Lily Pond coffee cup as a gift. Water Lily Pond is truly a masterpiece by Claude Monet, and now you can appreciate it on this high quality coffee cup.","images":["https://m.media-amazon.com/images/I/417nQPtxkbL._AC_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"MyHeritageWear","source_asin":"B007DAEDH6","category_path":"Home & Kitchen"},"sku":"BM-1032237","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B007DAEDH6","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B007DAEDH6","price_pending":true,"merchant_ready":false});
